"""Observability for one handled DTMF keypress."""

from __future__ import annotations

from contextlib import contextmanager
from typing import Iterator

from opentelemetry.trace import Span

from rasa.tracing.voice.metrics import (
    InteractionOutcome,
    record_dtmf_decision_metric,
)
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import add_event_to_current_span, voice_stage_span


class DtmfDecisionRecorder:
    """Record one handled keypress as span events and a decision metric.

    Records the keypress outcome and the number of buffered digits without
    capturing digit values. Only terminal decisions (accepted, ignored) count
    a DTMF decision; buffering events are span-only. Span writes are
    skipped when the wrapped span is non-recording (tracing disabled).
    """

    def __init__(self, span: Span) -> None:
        self.span = span

    def record_started(self) -> None:
        """Record that this keypress opened a new digit-collection window."""
        self._add_event(semconv.EVENT_DTMF_STARTED)

    def record_digit(self, buffered_count: int) -> None:
        """Count one buffered keypress — never the pressed digit's value."""
        self._add_event(semconv.EVENT_DTMF_DIGIT)
        if self.span.is_recording():
            self.span.set_attribute(semconv.VOICE_DTMF_BUFFER_LENGTH, buffered_count)

    def record_accepted(self) -> None:
        """Record that this keypress completed and composed a DTMF input."""
        record_dtmf_decision_metric(outcome=InteractionOutcome.ACCEPTED)
        self._add_event(semconv.EVENT_DTMF_ACCEPTED)

    def record_ignored(self) -> None:
        """Record a keypress that arrived without an active DTMF collect step."""
        record_dtmf_decision_metric(outcome=InteractionOutcome.IGNORED)
        self._add_event(semconv.EVENT_DTMF_IGNORED)

    def _add_event(self, name: str) -> None:
        if self.span.is_recording():
            self.span.add_event(name)


@contextmanager
def handle_dtmf_span() -> Iterator[DtmfDecisionRecorder]:
    """Open a `handle dtmf` span around one handled DTMF keypress.

    The span includes the lookup that resolves the active collect step.

    Yields:
        The decision recorder. Span writes are no-ops without tracing; metrics
        remain active when configured.
    """
    with voice_stage_span(semconv.SPAN_NAME_HANDLE_DTMF) as span:
        yield DtmfDecisionRecorder(span)


def record_dtmf_timeout() -> None:
    """Record an abandoned digit buffer as a timeout decision."""
    record_dtmf_decision_metric(outcome=InteractionOutcome.TIMEOUT)
    add_event_to_current_span(semconv.EVENT_DTMF_TIMEOUT)
